// dyna:mathx against values computed OUTSIDE this engine
// (tests/corpus/ref/mathx_vectors.js, generated by tools/gen_mathx_ref_vectors.py
// from mpmath at 60 digits, and exact rational arithmetic for the stats).
//
// Error is measured in units in the last place of the reference value. For
// functions that oscillate (Bessel J/Y, Airy on the negative axis, Legendre,
// Jacobi sn/cn) a relative error means nothing near a zero, so those are
// measured against the function's local envelope instead -- an absolute error
// scaled by the size the function has around that point.
//
// Each family's bar is stated below. A bar is a CLAIM about the
// implementation; when a row goes over it, the row names the argument, the
// reference and the ULP count, which is the bug report.
//
//   ./dynajs tests/mathx/test_mathx_ref.js            assert the bars
//   ./dynajs tests/mathx/test_mathx_ref.js --report   print each family's worst row
import * as mx from "dyna:mathx";
import { VECTORS } from "../corpus/ref/mathx_vectors.js";

const report = typeof scriptArgs !== "undefined" && scriptArgs.includes("--report");
let n = 0, fails = 0;
function fail(m) { fails++; print("FAIL: " + m); }

const F64 = new Float64Array(1), U64 = new BigUint64Array(F64.buffer);
function ulp(x) {
    x = Math.abs(x);
    if (!isFinite(x)) return NaN;
    if (x < 2.2250738585072014e-308) return 5e-324;
    F64[0] = x; U64[0] += 1n;
    return F64[0] - x;
}
// error of `got` against `want`, in ULPs of `scale` (the reference itself
// unless an envelope is given)
function err(got, want, scale) {
    if (Number.isNaN(want)) return Number.isNaN(got) ? 0 : Infinity;
    if (!isFinite(want)) return got === want ? 0 : Infinity;
    if (!isFinite(got)) return Infinity;
    if (got === want) return 0;
    const s = Math.max(Math.abs(want), scale === undefined ? 0 : Math.abs(scale));
    return Math.abs(got - want) / ulp(s);
}

// envelope helpers for the oscillating families
const envJY = (n, x) => {
    const ax = Math.abs(x), an = Math.abs(n);
    return ax > an + 1 ? Math.sqrt(2 / (Math.PI * ax)) : 0;
};
const envAiry = (x) => (x < -1 ? Math.pow(-x, -0.25) / Math.sqrt(Math.PI) : 0);
const envAiryP = (x) => (x < -1 ? Math.pow(-x, 0.25) / Math.sqrt(Math.PI) : 0);

// A value computed as exp(L) carries L's rounding into every ULP of the
// result: one ULP of L = -480 is ~600 ULPs of exp(L). Functions whose answer
// is such an exponential (beta, the incomplete gamma/beta tails) get a bar of
// base + k * |ln(value)|; near the centre of the distribution, where ln is
// small, that is just the base.
const tail = (base, k) => (args, want) => base + k * Math.abs(Math.log(Math.abs(want)) || 0);

// family -> [call(args) => number[] (one or more outputs), bar in ULPs (or a
//            function of (args, reference) giving one),
//            envelope(args, outputIndex) or undefined]
const FAMILIES = {
    gamma:          [(a) => [mx.gamma(a[0])], 16],
    gammaln:        [(a) => [mx.gammaln(a[0])], 8],
    psi:            [(a) => [mx.psi(a[0])], 16],
    erf:            [(a) => [mx.erf(a[0])], 4],
    erfc:           [(a) => [mx.erfc(a[0])], 8],
    erfcx:          [(a) => [mx.erfcx(a[0])], 32],
    erfinv:         [(a) => [mx.erfinv(a[0])], 8],
    erfcinv:        [(a) => [mx.erfcinv(a[0])], 16],
    expint:         [(a) => [mx.expint(a[0])], 32],
    expm1:          [(a) => [mx.expm1(a[0])], 2],
    log1p:          [(a) => [mx.log1p(a[0])], 2],
    beta:           [(a) => [mx.beta(a[0], a[1])], tail(64, 2)],
    betaln:         [(a) => [mx.betaln(a[0], a[1])], 32],
    polygamma:      [(a) => [mx.polygamma(a[0], a[1])], 64],
    gammainc_lower: [(a) => [mx.gammainc(a[0], a[1])], tail(64, 8)],
    gammainc_upper: [(a) => [mx.gammainc(a[0], a[1], "upper")], tail(64, 8)],
    betainc:        [(a) => [mx.betainc(a[0], a[1], a[2])], tail(256, 8)],
    gammaincinv:    [(a) => [mx.gammaincinv(a[0], a[1])], (a) => 256 + 16 / a[1]],
    betaincinv:     [(a) => [mx.betaincinv(a[0], a[1], a[2])], 256],
    besselj:        [(a) => [mx.besselj(a[0], a[1])], 64, (a) => envJY(a[0], a[1])],
    bessely:        [(a) => [mx.bessely(a[0], a[1])], 64, (a) => envJY(a[0], a[1])],
    besseli:        [(a) => [mx.besseli(a[0], a[1])], tail(64, 2)],
    besseliScaled:  [(a) => [mx.besseliScaled(a[0], a[1])], tail(64, 2)],
    besselk:        [(a) => [mx.besselk(a[0], a[1])], 64],
    besselkScaled:  [(a) => [mx.besselkScaled(a[0], a[1])], 64],
    besselh1:       [(a) => mx.besselh(a[0], a[1], 1), 64, (a) => envJY(a[0], a[1])],
    besselh2:       [(a) => mx.besselh(a[0], a[1], 2), 64, (a) => envJY(a[0], a[1])],
    ellipke:        [(a) => mx.ellipke(a[0]), 16],
    ellipj:         [(a) => { const r = mx.ellipj(a[0], a[1]); return [r.sn, r.cn, r.dn]; }, 64, () => 1],
    legendreP:      [(a) => [mx.legendreP(a[0], a[1], a[2])], 64, (a) => legScale(a[0], a[1])],
    legendre_col:   [(a) => mx.legendre(a[0], a[1]), 64, (a, i) => legScale(a[0], i)],
    // the power series still serves x = -5, where its terms cancel by about
    // two digits: measured 420 ULP of the envelope there (Bi'), 51 at -2.2
    airy:           [(a) => { const r = mx.airy(a[0]); return [r.ai, r.aip, r.bi, r.bip]; }, 512,
                     (a, i) => (i % 2 ? envAiryP(a[0]) : envAiry(a[0]))],
    gammainc_sweep: [(a) => [mx.gammainc(a[0], a[1]), mx.gammainc(a[0], a[1], "upper")], tail(64, 8)],
    betainc_sweep:  [(a) => [mx.betainc(a[0], a[1], a[2])], tail(256, 8)],
    // x = (p Gamma(a+1))^(1/a) near 0: one ULP of P is 1/a ULPs of x
    gammaincinv_sweep: [(a) => [mx.gammaincinv(a[0], a[1])], (a) => 256 + 16 / a[1]],
    betaln_sweep:   [(a) => [mx.betaln(a[0], a[1])], 64],
    polygamma_sweep: [(a) => [mx.polygamma(a[0], a[1])], 256],
    stats_sum:      [(a) => [mx.stats.sum(a[1])], 1],
    stats_mean:     [(a) => [mx.stats.mean(a[1])], 2],
    stats_variance: [(a) => [mx.stats.variance(a[1])], 16],
    stats_stddev:   [(a) => [mx.stats.stddev(a[1])], 16],
    stats_cov:      [(a) => [mx.stats.cov(a[1], a[2])], 16],
    stats_corr:     [(a) => [mx.stats.corr(a[1], a[2])], 16],
};
// |P_n^m| is bounded by about (n+m)!/(n-m)! ^ 1/2 on [-1, 1]; scale by the
// normalisation so a value near a zero of the polynomial is measured fairly
function legScale(nn, m) {
    let s = 1;
    for (let k = nn - m + 1; k <= nn + m; k++) s *= k;
    return Math.sqrt(s);
}

const seen = new Set();
for (const [fam, rows] of Object.entries(VECTORS)) {
    const spec = FAMILIES[fam];
    if (!spec) { fail("vectors carry family '" + fam + "' that this suite does not test"); continue; }
    seen.add(fam);
    const [call, bar, env] = spec;
    let worst = 0, worstAt = "";
    for (const [args, wantRaw] of rows) {
        const want = Array.isArray(wantRaw) ? wantRaw : [wantRaw];
        let got;
        try { got = call(args); } catch (e) { n++; fail(fam + "(" + JSON.stringify(args) + ") threw " + e.message); continue; }
        if (!got || got.length !== want.length) { n++; fail(fam + "(" + JSON.stringify(args) + ") returned " + JSON.stringify(got) + ", want " + want.length + " values"); continue; }
        for (let i = 0; i < want.length; i++) {
            n++;
            const e = err(got[i], want[i], env ? env(args, i) : undefined);
            const b = typeof bar === "function" ? bar(args, want[i]) : bar;
            const at = fam + "(" + JSON.stringify(args).slice(0, 60) + ")" + (want.length > 1 ? "[" + i + "]" : "") +
                " = " + got[i] + ", reference " + want[i] + " (" + (isFinite(e) ? e.toFixed(1) : e) + " ulp, bar " + Math.round(b) + ")";
            if (e / b > worst) { worst = e / b; worstAt = at; }
            if (!report && !(e <= b)) fail(at);
        }
    }
    if (report) print((fam + "                ").slice(0, 18) + " worst/bar " + (isFinite(worst) ? worst.toFixed(2) : worst) + "  " + worstAt);
}
for (const fam of Object.keys(FAMILIES)) if (!seen.has(fam)) fail("family '" + fam + "' has no vectors -- regenerate tests/corpus/ref/mathx_vectors.js");

// edges the contract fixes rather than a reference value
const EDGES = [
    ["gamma(+0)", () => mx.gamma(0), Infinity],
    ["gamma(-0)", () => mx.gamma(-0), -Infinity],
    ["gamma(-3) (pole)", () => mx.gamma(-3), NaN],
    ["gamma(NaN)", () => mx.gamma(NaN), NaN],
    ["gamma(-190.5) underflows to -0", () => mx.gamma(-190.5), -0],
    ["gamma(-177.5) is subnormal and positive", () => mx.gamma(-177.5) > 0 && mx.gamma(-177.5) < 2.2250738585072014e-308, true],
    ["psi(0) is -Infinity from the right", () => mx.psi(0), -Infinity],
    ["psi(-2) (pole)", () => mx.psi(-2), NaN],
    ["polygamma(2, -3) (pole)", () => mx.polygamma(2, -3), NaN],
    ["ellipke(1) = [Infinity, 1]", () => mx.ellipke(1), [Infinity, 1]],
    ["ellipke(1.5) is NaN", () => mx.ellipke(1.5).every(Number.isNaN), true],
    ["variance of one value (sample) is NaN", () => mx.stats.variance([3]), NaN],
    ["variance of one value (pop) is 0", () => mx.stats.variance([3], { pop: true }), 0],
    ["variance of a constant at 1e15 is 0", () => mx.stats.variance(new Array(100).fill(1e15 + 1)), 0],
];
for (const [name, fn, want] of EDGES) {
    n++;
    let got;
    try { got = fn(); } catch (e) { fail(name + " threw " + e.message); continue; }
    const same = Array.isArray(want) ? Array.isArray(got) && want.every((w, i) => Object.is(got[i], w)) : Object.is(got, want);
    if (!same) fail(name + ": got " + (Array.isArray(got) ? JSON.stringify(got) : String(Object.is(got, -0) ? "-0" : got)) + ", want " + String(Object.is(want, -0) ? "-0" : want));
}

print("test_mathx_ref: " + n + " checks, " + fails + " failures");
if (fails) throw new Error(fails + " failures");
